    if (!task || ![...TRAINING_KEYS, "healing"].includes(kind)) return;
    if (itemId && (!item || !["universal", isTrainingQueue(kind) ? "troop" : "heal"].includes(item.family))) return showBuildNotice("این آیتم برای این صف قابل استفاده نیست.");
